{
  "PROP-56ad1eb2-inv-032": {
    "property_id": "PROP-56ad1eb2-inv-032",
    "audit_result": {
      "property_id": "PROP-56ad1eb2-inv-032",
      "classification": "potential-vulnerability",
      "code_path": "beacon-chain/sync/validate_beacon_blocks.go::detectAndBroadcastEquivocation::L498-501",
      "proof_trace": "Signature verification is bypassed when a seen block arrives but the chain head has moved to a different (slot, proposer). The equivocation detector early-returns without calling VerifyProposerSlashing if headBlock slot/proposer doesn't match incoming block, allowing resubmitted blocks with invalid signatures to be ignored unverified.",
      "attack_scenario": "Attacker sends Block A (valid) at slot N which becomes head and is cached. Chain advances to slot N+1. Attacker resends slot N with same proposer but crafted invalid signature. The seen-cache triggers equivocation check, but head mismatch causes early return at L498-501, bypassing signature verification entirely.",
      "checklist_id": "PROP-56ad1eb2-inv-032"
    },
    "text": "Dedup cache hit must not bypass signature verification on resubmitted items with different proofs.",
    "assertion": "forall item, seen_set: item.id in seen_set => verify_signature(item.sig) must still execute on new instance",
    "covers": "SG-003",
    "severity": "HIGH",
    "type": "invariant"
  }
}

